/// <summary>Constuct new object</summary>
/// <param name = "_args">Arguments</param>
/// <param name = "_executionMode">Execution mode</param>
/// <returns>New Controller Object</returns>
public static METTAMRebateDealWorkflowSubmitController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METTAMRebateDealWorkflowSubmitController controller = new METTAMRebateDealWorkflowSubmitController();
    controller.parmExecutionMode(_executionMode);
    controller.parmArgs(_args);

    return controller;
}

/// <summary>
/// New method specifying the service class method to call
/// </summary>
protected void new()
{
    super(classstr(METTAMRebateDealWorkflowSubmitService), methodstr(METTAMRebateDealWorkflowSubmitService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Main method
/// </summary>
/// <param name = "_args">Arguments</param>
public static void main(Args _args)
{
    // create controller
    METTAMRebateDealWorkflowSubmitController controller = METTAMRebateDealWorkflowSubmitController::construct(_args);

    // execute the service class
    controller.startOperation();        
}

/// <summary>
